1	import { createServer } from 'node:http';
2	import type { IncomingMessage, ServerResponse } from 'node:http';
3	import { lstatSync, mkdirSync, readFileSync, renameSync, unlinkSync, writeFileSync } from 'node:fs';
4	import { join } from 'node:path';
5	import { randomUUID } from 'node:crypto';
6	import {
7	  FIELD_LIMITS,
8	  checkIdeaContent,
9	  isCompleteIdea,
10	  normalizeIdea,
11	  fieldRulesBrowserScript,
12	  type ContentErrorCode,
13	} from './idea-fields.ts';
14	
15	const PRODUCT: string = 'FeatureHarbor';
16	const RESOURCE: string = 'ideas';
17	const MAX_BODY_BYTES = 1_000_000;
18	// 严格 UTF-8 解码器：fatal 模式遇到非法字节直接抛错，而不是像 Buffer.toString('utf8')
19	// 那样把坏字节静默替换成“�”。请求正文与磁盘上的已有意见都先在完整的字节缓冲上通过它，
20	// 才允许进入 JSON 解析；分段送达在缓冲拼接后判断，合法多字节字符被拆到相邻段不算损坏。
21	const UTF8_DECODER = new TextDecoder('utf-8', { fatal: true });
22	// 接口侧把共用的内容判定结果映射成原有的错误说明；首页另有自己的措辞。
23	const CONTENT_ERROR_MESSAGES: Record<ContentErrorCode, string> = {
24	  'title-empty': '标题去掉首尾空白后不能为空',
25	  'title-too-long': `标题最多 ${FIELD_LIMITS.title} 个字符`,
26	  'description-empty': '详细说明必须包含非空白内容',
27	  'description-too-long': `详细说明最多 ${FIELD_LIMITS.description} 个字符`,
28	  'scenario-too-long': `使用场景最多 ${FIELD_LIMITS.scenario} 个字符`,
29	};
30	const PAGE: string = `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FeatureHarbor · 产品意见与公开路线图</title><style>
31	body{font-family:system-ui,sans-serif;max-width:52rem;margin:3rem auto;padding:0 1rem;line-height:1.7}
32	a{color:#175b9c}
33	label{display:block;font-weight:600;margin-top:1rem}
34	input,textarea{width:100%;box-sizing:border-box;padding:.4rem;font:inherit}
35	textarea{resize:vertical}
36	.required{color:#b00020}
37	button{margin-top:1rem;padding:.5rem 1.2rem;font:inherit}
38	#error{color:#b00020;margin-top:.75rem}
39	#success{color:#1a7f37;margin-top:.75rem}
40	.idea{border-top:1px solid #ddd;padding:1rem 0}
41	.idea h3{margin:0 0 .5rem}
42	.pre{white-space:pre-wrap}
43	time{color:#666;font-size:.9rem}
44	#search-form{margin:1rem 0}
45	#search-form input{max-width:20rem;margin-right:.5rem}
46	#search-form button{margin-top:.25rem;margin-right:.5rem}
47	</style><main><h1>FeatureHarbor</h1><p>产品意见与公开路线图</p>
48	<h2>提交产品意见</h2>
49	<form id="idea-form" novalidate>
50	<label for="f-title">标题 <span class="required">*</span>（必填，最多 ${FIELD_LIMITS.title} 字）</label>
51	<input id="f-title" name="title" required>
52	<label for="f-desc">详细说明 <span class="required">*</span>（必填，最多 ${FIELD_LIMITS.description} 字）</label>
53	<textarea id="f-desc" name="description" rows="5" required></textarea>
54	<label for="f-scenario">使用场景（可选，最多 ${FIELD_LIMITS.scenario} 字）</label>
55	<textarea id="f-scenario" name="scenario" rows="3"></textarea>
56	<button type="submit">提交意见</button>
57	<p id="error" role="alert" hidden></p>
58	<p id="success" role="status" hidden></p>
59	</form>
60	<h2>意见列表</h2>
61	<form id="search-form" role="search" novalidate>
62	<label for="f-search">关键词搜索</label>
63	<input id="f-search" name="q" type="search" placeholder="搜索标题、详细说明或使用场景" autocomplete="off">
64	<button type="submit">搜索</button>
65	<button id="search-clear" type="button">清空</button>
66	</form>
67	<p id="empty" hidden>还没有意见记录。</p>
68	<div id="ideas"></div>
69	<p><a href="/api/ideas">查看意见列表接口</a> · <a href="/health">服务状态</a></p>
70	</main><script>
71	${fieldRulesBrowserScript}
72	const form = document.getElementById('idea-form');
73	const titleInput = document.getElementById('f-title');
74	const descInput = document.getElementById('f-desc');
75	const scenarioInput = document.getElementById('f-scenario');
76	const errorBox = document.getElementById('error');
77	const successBox = document.getElementById('success');
78	const emptyNote = document.getElementById('empty');
79	const list = document.getElementById('ideas');
80	const searchForm = document.getElementById('search-form');
81	const searchInput = document.getElementById('f-search');
82	const searchClear = document.getElementById('search-clear');
83	const EMPTY_TEXT = '还没有意见记录。';
84	const NOT_FOUND_TEXT = '没有找到符合关键词的意见。';
85	const LOAD_FAILED_TEXT = '意见列表加载失败，请稍后刷新重试。';
86	// 首次列表请求的状态：loading（进行中）/ ready（成功）/ failed（失败）
87	let listState = 'loading';
88	// 已生效的搜索关键词：去掉首尾空白后的完整一段文字，空字符串表示不搜索。
89	// 只影响当前页面的可见结果，不发起请求、不改变已保存记录与接口返回。
90	let activeKeyword = '';
91	// 纯文字的大小写不敏感包含判断：关键词内部空格按原文参与比较，
92	// 不拆词；标点、尖括号与看起来像正则表达式的文字都按普通文字查找，
93	// 因此直接用 includes，不能走正则。
94	function ideaMatches(idea, keyword) {
95	  const needle = keyword.toLowerCase();
96	  return idea.title.toLowerCase().includes(needle)
97	    || idea.description.toLowerCase().includes(needle)
98	    || idea.scenario.toLowerCase().includes(needle);
99	}
100	function showError(message) {
101	  errorBox.textContent = message;
102	  errorBox.hidden = false;
103	  successBox.hidden = true;
104	}
105	function renderIdea(idea) {
106	  const item = document.createElement('article');
107	  item.className = 'idea';
108	  const heading = document.createElement('h3');
109	  heading.textContent = idea.title;
110	  const desc = document.createElement('p');
111	  desc.className = 'pre';
112	  desc.textContent = idea.description;
113	  item.append(heading, desc);
114	  if (typeof idea.scenario === 'string' && idea.scenario.trim().length > 0) {
115	    const scenario = document.createElement('p');
116	    const label = document.createElement('strong');
117	    label.textContent = '使用场景：';
118	    const text = document.createElement('span');
119	    text.className = 'pre';
120	    text.textContent = idea.scenario;
121	    scenario.append(label, text);
122	    item.append(scenario);
123	  }
124	  const time = document.createElement('time');
125	  time.dateTime = idea.createdAt;
126	  const parsed = new Date(idea.createdAt);
127	  time.textContent = isNaN(parsed.getTime()) ? String(idea.createdAt) : parsed.toLocaleString();
128	  item.append(time);
129	  return item;
130	}
131	let remoteIdeas = [];
132	// 本页已确认保存的意见，按本页发起提交的先后排列：后提交的在前。
133	// 每条记录带上点击提交时的序号，响应返回的先后不影响排列位置
134	const submittedIdeas = [];
135	function renderList() {
136	  // 以服务端标识 id 去重后合并：本页提交成功的意见在前，其后补入首次响应中的其他记录
137	  const seen = new Set();
138	  const ordered = [];
139	  for (const entry of submittedIdeas) {
140	    const idea = entry.idea;
141	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
142	  }
143	  for (const idea of remoteIdeas) {
144	    if (!seen.has(idea.id)) { seen.add(idea.id); ordered.push(idea); }
145	  }
146	  // 搜索只过滤当前页面的可见结果：沿用合并后的原有顺序，逐条判断、不去重不重排，
147	  // 同一条意见最多出现一次；匹配的意见仍按原文渲染（保留空白与换行），不删改内容。
148	  const visible = activeKeyword
149	    ? ordered.filter((idea) => ideaMatches(idea, activeKeyword))
150	    : ordered;
151	  list.replaceChildren(...visible.map(renderIdea));
152	  if (listState === 'failed') {
153	    // 加载失败优先显示现有的失败提示，不能把失败显示成搜索无结果
154	    emptyNote.textContent = LOAD_FAILED_TEXT;
155	    emptyNote.hidden = false;
156	  } else if (listState !== 'ready') {
157	    // 首次列表仍在加载，不能把等待误报成没有记录或没有匹配结果
158	    emptyNote.hidden = true;
159	  } else if (activeKeyword) {
160	    // 搜索已生效：完整列表是否为空决定提示措辞，已有意见但无匹配时明确提示未找到
161	    emptyNote.textContent = ordered.length === 0 ? EMPTY_TEXT : NOT_FOUND_TEXT;
162	    emptyNote.hidden = visible.length > 0;
163	  } else {
164	    emptyNote.textContent = EMPTY_TEXT;
165	    emptyNote.hidden = ordered.length > 0;
166	  }
167	}
168	// 一条意见记录是否完整，直接使用 idea-fields.ts 注入的同一份 isCompleteIdea：
169	// 与服务读取已有数据的判定逐字相同，列表加载与提交确认都调用它，不在页面另写第二份。
170	async function loadIdeas() {
171	  try {
172	    const res = await fetch('/api/ideas');
173	    if (!res.ok) throw new Error('load failed');
174	    const data = await res.json();
175	    // 列表响应必须是带 ideas 数组的 JSON 对象，且数组中每条记录都完整；
176	    // 顶层结构异常或任意一条记录不完整都属于整次加载失败，
177	    // 即使异常记录前面有正常意见，也不能只展示其中一部分
178	    if (typeof data !== 'object' || data === null || Array.isArray(data) || !Array.isArray(data.ideas)) {
179	      throw new Error('invalid ideas response');
180	    }
181	    if (!data.ideas.every(isCompleteIdea)) throw new Error('invalid idea record');
182	    remoteIdeas = data.ideas;
183	    listState = 'ready';
184	  } catch {
185	    listState = 'failed';
186	  }
187	  renderList();
188	}
189	// 任一字段每次发生编辑都递增；提交时记下当前版本，成功响应到达时若版本未变，
190	// 说明等待期间没有继续编辑，才清空表单，否则保留正在写的草稿
191	let editVersion = 0;
192	for (const field of [titleInput, descInput, scenarioInput]) {
193	  field.addEventListener('input', () => { editVersion += 1; });
194	}
195	// 字段内容判定与接口共用同一份实现（FIELD_LIMITS、codePointCount、checkIdeaContent
196	// 由 idea-fields.ts 注入）；这里只把共用判定结果映射成本页原有的提示措辞与顺序。
197	function validate(title, description, scenario) {
198	  switch (checkIdeaContent(title, description, scenario)) {
199	    case 'title-empty': return '标题不能为空。';
200	    case 'title-too-long': return '标题最多 ' + FIELD_LIMITS.title + ' 个字符。';
201	    case 'description-empty': return '详细说明不能为空。';
202	    case 'description-too-long': return '详细说明最多 ' + FIELD_LIMITS.description + ' 个字符。';
203	    case 'scenario-too-long': return '使用场景最多 ' + FIELD_LIMITS.scenario + ' 个字符。';
204	    default: return null;
205	  }
206	}
207	// 每次点击提交都递增：成功或失败提示只属于最近一次点击。
208	// 更早发出的请求即使更晚返回，也只能在服务确认保存时更新列表，不能改动当前提示。
209	let latestSubmitSeq = 0;
210	form.addEventListener('submit', async (event) => {
211	  event.preventDefault();
212	  const submitSeq = ++latestSubmitSeq;
213	  // 用户发起新的提交后，上一条操作的提示先清除；在本次点击有结果前，
214	  // 更早请求迟到返回也不能重新显示成功或失败，也不能让人误以为正在提交的意见已保存
215	  errorBox.hidden = true;
216	  successBox.hidden = true;
217	  const title = titleInput.value;
218	  const description = descInput.value;
219	  const scenario = scenarioInput.value;
220	  const submittedVersion = editVersion;
221	  const problem = validate(title, description, scenario);
222	  // 被表单直接拦下的一次点击同样是用户最近的提交操作，字段错误即本次点击的结果；
223	  // 之后更早请求的返回不能掩盖它
224	  if (problem) { showError(problem); return; }
225	  let res;
226	  try {
227	    res = await fetch('/api/ideas', {
228	      method: 'POST',
229	      headers: { 'content-type': 'application/json' },
230	      body: JSON.stringify({ title, description, scenario })
231	    });
232	  } catch {
233	    if (submitSeq === latestSubmitSeq) showError('网络错误，提交未成功，请重试。');
234	    return;
235	  }
236	  let data = null;
237	  try { data = await res.json(); } catch { data = null; }
238	  if (!res.ok) {
239	    if (submitSeq === latestSubmitSeq) {
240	      showError(data && data.error ? '提交失败：' + data.error : '提交失败，请稍后重试。');
241	    }
242	    return;
243	  }
244	  // 成功状态的响应同样必须记录完整：顶层是含 idea 的 JSON 对象，
245	  // 且 idea 本身通过 isCompleteIdea 校验（对象、非空 id、各字段均为字符串）。
246	  // 空对象、数组或缺字段的记录不能当作保存成功：不显示成功提示、
247	  // 不清空草稿、不并入列表，也不用表单内容补齐响应缺失的信息
248	  const saved = typeof data === 'object' && data !== null && !Array.isArray(data) && isCompleteIdea(data.idea);
249	  if (!saved) {
250	    if (submitSeq === latestSubmitSeq) showError('提交失败，请稍后重试。');
251	    return;
252	  }
253	  const idea = data.idea;
254	  // 是否清空表单只取决于等待期间有没有继续编辑（包括改回原文、清空字段也算编辑），
255	  // 与响应返回先后无关：过期请求确认保存时也不能清掉用户正在写的草稿
256	  if (editVersion === submittedVersion) form.reset();
257	  // 只要服务确认保存，意见就进入列表，即使这条请求已不是最近一次点击：
258	  // 不能为了避免提示干扰而丢弃真实保存结果。
259	  // 位置按本页发起提交的先后确定（后提交的在前），与响应返回先后无关：
260	  // 先提交的意见迟到确认时补到后提交的意见之后，不能把它挤到更靠后的位置
261	  const entry = { seq: submitSeq, idea };
262	  let insertAt = submittedIdeas.findIndex((e) => e.seq < submitSeq);
263	  if (insertAt === -1) insertAt = submittedIdeas.length;
264	  submittedIdeas.splice(insertAt, 0, entry);
265	  renderList();
266	  // 成功提示只属于最近一次点击：更早的请求迟到返回时，不能在最新一次的失败提示
267	  // 或新一次提交的等待旁边再显示成功
268	  if (submitSeq === latestSubmitSeq) {
269	    successBox.textContent = '提交成功，你的意见已保存。';
270	    successBox.hidden = false;
271	  }
272	});
273	// 搜索只在本页过滤已合并的完整列表：提交搜索表单不发起任何请求、不提交意见，
274	// 也不清空或改写提交意见表单里的草稿；关键词去掉首尾空白后为空时恢复完整列表。
275	// 已生效后，迟到的首次列表与本页新确认保存的意见都会在 renderList 中继续按它过滤。
276	function applySearch() {
277	  activeKeyword = searchInput.value.trim();
278	  renderList();
279	}
280	searchForm.addEventListener('submit', (event) => {
281	  event.preventDefault();
282	  applySearch();
283	});
284	searchClear.addEventListener('click', () => {
285	  searchInput.value = '';
286	  activeKeyword = '';
287	  renderList();
288	});
289	loadIdeas();
290	</script></html>`;
291	const args: string[] = process.argv.slice(2);
292	const help: string = `FeatureHarbor - 产品意见与公开路线图
293	Usage: node server.ts serve [--host ADDRESS] [--port PORT] [--data-dir DIRECTORY]
294	       node server.ts --help
295	Defaults: --host 127.0.0.1 --port 8080 --data-dir data
296	Port 0 selects an available port.
297	`;
298	if (args.length === 0 || args.includes('--help') || args.includes('-h')) {
299	  process.stdout.write(help);
300	  process.exit(args.length === 0 ? 2 : 0);
301	}
302	if (args.shift() !== 'serve') { console.error('Expected serve or --help'); process.exit(2); }
303	let host: string = '127.0.0.1';
304	let port: number = 8080;
305	let dataDir: string = 'data';
306	while (args.length) {
307	  const flag = args.shift();
308	  const value = args.shift();
309	  if (!value || !['--host', '--port', '--data-dir'].includes(flag ?? '')) {
310	    console.error('Each option must be --host, --port or --data-dir followed by a value'); process.exit(2);
311	  }
312	  if (flag === '--host') host = value;
313	  else if (flag === '--port') {
314	    if (!/^\d+$/.test(value) || Number(value) > 65535) { console.error('Port must be between 0 and 65535'); process.exit(2); }
315	    port = Number(value);
316	  } else dataDir = value;
317	}
318	mkdirSync(dataDir, { recursive: true });
319	const dataFile = join(dataDir, 'ideas.json');
320	try { writeFileSync(dataFile, '[]\n', { flag: 'wx' }); } catch (error) {
321	  if (!(error instanceof Error && 'code' in error && error.code === 'EEXIST')) throw error;
322	}
323	function respond(res: ServerResponse, status: number, value: unknown, options: { html?: boolean; allow?: string } = {}): void {
324	  const body = options.html ? String(value) : JSON.stringify(value);
325	  res.writeHead(status, { 'content-type': options.html ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
326	    'content-length': Buffer.byteLength(body), ...(status === 405 ? { allow: options.allow ?? 'GET' } : {}) });
327	  res.end(body);
328	}
329	// 已有意见的结构完整性直接使用 idea-fields.ts 的 isCompleteIdea，
330	// 与首页列表加载、提交结果确认共用同一份判定。
331	function readIdeas(): unknown[] {
332	  // 先拿到原始字节并用 fatal TextDecoder 严格解码，再交给 JSON.parse：
333	  // readFileSync(path, 'utf8') 内部走 Buffer.toString('utf8')，会把非法 UTF-8 字节
334	  // 静默替换成“�”。替换后的文字若仍能组成完整记录，列表就会正常返回；此后提交新意见
335	  // 还会把替换后的旧内容一并保存，原始字节就此被改写。因此这里绝不能按“文字里有没有
336	  // �”判断（用户主动写下的“�”是以合法 UTF-8 EF BF BD 编码的普通文字，必须照常读取），
337	  // 而要由保存内容的实际字节编码决定：单独的续字节、缺少后续字节的多字节字符、不符合
338	  // UTF-8 规则的编码，无论出现在标题、详细说明、使用场景还是其他位置，都让整份数据
339	  // 读取失败——不替换、不忽略、不只读取其中的正常片段。
340	  const raw = readFileSync(dataFile);
341	  let text: string;
342	  try {
343	    text = UTF8_DECODER.decode(raw);
344	  } catch {
345	    throw new Error('Invalid UTF-8 in ideas storage');
346	  }
347	  const records: unknown = JSON.parse(text);
348	  if (!Array.isArray(records)) throw new Error('Invalid record list');
349	  // 任意一条记录不完整，整份列表都视为读取失败：
350	  // 不跳过异常记录，也不只返回正常部分。只检查结构，不套用新提交的内容限制：
351	  // 标题首尾空白、正文与场景换行、任意时间字符串都按原样保留，不补字段或改写文字。
352	  if (!records.every(isCompleteIdea)) throw new Error('Invalid idea record');
353	  return records;
354	}
355	function saveIdeas(records: unknown[]): void {
356	  const tempFile = `${dataFile}.tmp`;
357	  writeFileSync(tempFile, `${JSON.stringify(records, null, 2)}\n`);
358	  try {
359	    renameSync(tempFile, dataFile);
360	  } catch (error) {
361	    // 临时内容已写入但替换正式文件失败：尽量删除本次写出的临时普通文件，
362	    // 不让未保存成功的内容留下可被误认成已保存数据的副本。
363	    // 清理只针对普通文件——临时路径若是目录等本就不是本次写出的形态，一律不动；
364	    // 清理本身失败（如权限限制）只放弃清理，不掩盖原有的保存失败。
365	    try {
366	      if (lstatSync(tempFile).isFile()) unlinkSync(tempFile);
367	    } catch {
368	      // 忽略清理异常：保存失败的结果不变
369	    }
370	    throw error;
371	  }
372	}
373	async function handleCreateIdea(req: IncomingMessage, res: ServerResponse): Promise<void> {
374	  // 请求大小上限按实际收到的字节累计：JSON 的括号、引号、字段名与空白都计入，
375	  // 中文、表情按 UTF-8 编码后的字节数计入；这与字段按 Unicode 码点的上限是两回事。
376	  const declaredLength = Number(req.headers['content-length']);
377	  let tooLarge = Number.isFinite(declaredLength) && declaredLength > MAX_BODY_BYTES;
378	  const chunks: Buffer[] = [];
379	  let size = 0;
380	  // 超限后不能写出 400 就立即 req.destroy()：客户端可能还在发送，强断会让它只看到
381	  // 连接断开，读不到完整错误。这里继续把请求体读完（排空，天然带背压），
382	  // 等请求正常结束后再回复，客户端只要发完并保持连接等待，就能收到完整可解析的 400。
383	  // 超限后的字节不再缓存：绝不能拿已收到的前缀去解析，更不能截断后尝试保存。
384	  try {
385	    for await (const chunk of req as AsyncIterable<Buffer>) {
386	      size += chunk.length;
387	      if (tooLarge) continue;
388	      if (size > MAX_BODY_BYTES) {
389	        tooLarge = true;
390	        chunks.length = 0;
391	        continue;
392	      }
393	      chunks.push(chunk);
394	    }
395	  } catch {
396	    // 客户端中途断开或请求流出错：响应已无处可写，安静结束，不能变成 500。
397	    req.destroy();
398	    return;
399	  }
400	  // 无论是否预先声明长度（Content-Length）还是分段传输（Transfer-Encoding: chunked）、
401	  // 超出发生在中途还是末段，都按同一条规则拒绝；即使正文同时不是合法 UTF-8 或合法 JSON，
402	  // 理由也仍是“请求体过大”，不能被后续的 UTF-8/JSON 解析替换成别的错误。
403	  // 恰好达到上限（size === MAX_BODY_BYTES）不在这里拒绝，继续按 JSON 与字段规则判断。
404	  if (tooLarge) {
405	    respond(res, 400, { error: '请求体过大' });
406	    return;
407	  }
408	  // 先按 UTF-8 严格解码整份正文，再解析 JSON：非法字节（单独的续字节、缺少后续
409	  // 字节的多字节字符、不符合 UTF-8 规则的编码）无论在标题、说明、场景还是正文其他
410	  // 位置，都让整次提交失败，不能把坏字节替换成“�”、删字节或只解析正常片段。
411	  // 用户主动输入的“�”本身以合法 UTF-8（EF BF BD）编码，解码结果就是普通文字，照常进入后续判定。
412	  const rawBody = Buffer.concat(chunks);
413	  let bodyText: string;
414	  try {
415	    bodyText = UTF8_DECODER.decode(rawBody);
416	  } catch {
417	    respond(res, 400, { error: '请求体不是有效的 UTF-8' });
418	    return;
419	  }
420	  let payload: unknown;
421	  try {
422	    payload = JSON.parse(bodyText);
423	  } catch {
424	    respond(res, 400, { error: '请求体不是有效的 JSON' });
425	    return;
426	  }
427	  if (typeof payload !== 'object' || payload === null || Array.isArray(payload)) {
428	    respond(res, 400, { error: '请求体必须是 JSON 对象' });
429	    return;
430	  }
431	  const body = payload as Record<string, unknown>;
432	  for (const field of ['title', 'description'] as const) {
433	    if (body[field] === undefined) { respond(res, 400, { error: `缺少必填字段 ${field}` }); return; }
434	    if (typeof body[field] !== 'string') { respond(res, 400, { error: `字段 ${field} 必须是字符串` }); return; }
435	  }
436	  if (body.scenario !== undefined && typeof body.scenario !== 'string') {
437	    respond(res, 400, { error: '字段 scenario 必须是字符串' });
438	    return;
439	  }
440	  const rawTitle = body.title as string;
441	  const rawDescription = body.description as string;
442	  const scenario = typeof body.scenario === 'string' ? body.scenario : '';
443	  // 内容规则（空白与上限）与首页共用同一份判定，这里只保留接口原有的错误措辞。
444	  const problem = checkIdeaContent(rawTitle, rawDescription, scenario);
445	  if (problem) {
446	    respond(res, 400, { error: CONTENT_ERROR_MESSAGES[problem] });
447	    return;
448	  }
449	  const { title, description } = normalizeIdea(rawTitle, rawDescription, scenario);
450	  const idea = {
451	    id: randomUUID(),
452	    title,
453	    description,
454	    scenario,
455	    createdAt: new Date().toISOString(),
456	  };
457	  let records: unknown[];
458	  try {
459	    records = readIdeas();
460	  } catch {
461	    respond(res, 500, { error: '无法读取已有意见数据，未保存新意见' });
462	    return;
463	  }
464	  records.unshift(idea);
465	  try {
466	    saveIdeas(records);
467	  } catch {
468	    respond(res, 500, { error: '保存意见失败，请稍后重试' });
469	    return;
470	  }
471	  respond(res, 201, { idea });
472	}
473	const server = createServer((req: IncomingMessage, res: ServerResponse): void => {
474	  let route: string;
475	  try { route = new URL(req.url ?? '/', 'http://localhost').pathname; } catch { respond(res, 400, { error: 'invalid request path' }); return; }
476	  if (!['/', '/health', '/api/ideas'].includes(route)) { respond(res, 404, { error: 'not found' }); return; }
477	  if (route === '/api/ideas') {
478	    if (req.method === 'POST') {
479	      handleCreateIdea(req, res).catch(() => {
480	        if (!res.headersSent) respond(res, 500, { error: '提交意见失败，请稍后重试' });
481	      });
482	      return;
483	    }
484	    if (req.method !== 'GET') { respond(res, 405, { error: 'method not allowed' }, { allow: 'GET, POST' }); return; }
485	    try {
486	      respond(res, 200, { [RESOURCE]: readIdeas() });
487	    } catch { respond(res, 500, { error: 'unable to read ideas' }); }
488	    return;
489	  }
490	  if (req.method !== 'GET') { respond(res, 405, { error: 'method not allowed' }); return; }
491	  if (route === '/') { respond(res, 200, PAGE, { html: true }); return; }
492	  respond(res, 200, { status: 'ok', product: PRODUCT });
493	});
494	server.once('error', (error: Error): void => { console.error(error.message); process.exitCode = 1; });
495	server.listen(port, host, (): void => {
496	  const address = server.address();
497	  if (address && typeof address !== 'string') {
498	    const displayedHost = address.address.includes(':') ? `[${address.address}]` : address.address;
499	    console.log(`${PRODUCT} listening on http://${displayedHost}:${address.port}`);
500	  }
501	});
502	for (const signal of ['SIGINT', 'SIGTERM'] as const) {
503	  process.on(signal, (): void => { server.close(() => { process.exitCode = 0; }); server.closeIdleConnections(); });
504	}
