139	
140	const SUCCESS_TEXT = '提交成功，你的意见已保存。';
141	const EMPTY_TEXT = '还没有意见记录。';
142	const NOT_FOUND_TEXT = '没有找到符合关键词的意见。';
143	const LOAD_FAILED_TEXT = '意见列表加载失败，请稍后刷新重试。';
