147	class Harness {
148	  els: Record<string, El> = {};
149	  // 页面脚本通过 document.createElement 创建过的全部元素（按创建先后），
150	  // 用于断言渲染只产生纯文本结构，不为意见内容创建脚本、图片、链接、表单等元素
151	  created: El[] = [];
152	  gets: Gate[] = [];
153	  getsIssued = 0;
154	  posts: Gate[] = [];
155	  postsIssued = 0;
156	  postBodies: unknown[] = [];
157	
158	  constructor(script: string) {
159	    const byId: Map<string, El> = new Map();
160	    const register = (id: string, tag: string, hidden = false): El => {
161	      const node = makeElement(tag);
162	      node.hidden = hidden;
163	      byId.set(id, node);
164	      this.els[id] = node;
165	      return node;
166	    };
167	    const form = register('idea-form', 'form');
168	    const titleInput = register('f-title', 'input');
169	    const descInput = register('f-desc', 'textarea');
170	    const scenarioInput = register('f-scenario', 'textarea');
171	    register('search-form', 'form');
172	    register('f-search', 'input');
173	    register('search-clear', 'button');
174	    register('error', 'p', true);
175	    register('success', 'p', true);
176	    register('empty', 'p', true);
177	    register('ideas', 'div');
178	    form.reset = (): void => {
179	      titleInput.value = '';
180	      descInput.value = '';
181	      scenarioInput.value = '';
182	    };
183	    const documentMock = {
184	      getElementById: (id: string): El => byId.get(id)!,
185	      createElement: (tag: string): El => {
186	        const el = makeElement(tag);
187	        this.created.push(el);
188	        return el;
189	      },
190	    };
191	    const fetchMock = (url: unknown, init?: { method?: string; body?: unknown }): Promise<unknown> => {
192	      const method = init?.method ?? 'GET';
193	      const pending = gate();
194	      if (method === 'POST') {
195	        this.posts.push(pending);
196	        this.postsIssued += 1;
197	        this.postBodies.push(init?.body);
198	      } else {
199	        this.gets.push(pending);
200	        this.getsIssued += 1;
201	      }
202	      return pending.promise;
203	    };
204	    const context = vm.createContext({ console, document: documentMock, fetch: fetchMock });
205	    vm.runInContext(script, context, { filename: 'inline-page-script.js' });
206	  }
207	
208	  setForm(values: { title?: string; description?: string; scenario?: string }): void {
209	    if (values.title !== undefined) this.els['f-title'].value = values.title;
210	    if (values.description !== undefined) this.els['f-desc'].value = values.description;
211	    if (values.scenario !== undefined) this.els['f-scenario'].value = values.scenario;
212	  }
213	
214	  // 模拟真实用户输入：赋值并触发 input 事件（setForm 不触发事件，只用于布置初始状态）
215	  edit(id: string, value: string): void {
216	    const el = this.els[id];
217	    el.value = value;
218	    for (const fn of el.listeners.input ?? []) fn({ target: el });
219	  }
220	
221	  // 触发表单 submit 监听器，返回监听器（async 函数）的 Promise
222	  submit(): Promise<unknown> {
223	    const handler = this.els['idea-form'].listeners.submit[0];
224	    return handler({ preventDefault(): void {} });
225	  }
226	
227	  // 在搜索框布置文字（不触发事件）并点击“搜索”，返回监听器的返回值
228	  search(keyword: string): unknown {
229	    this.els['f-search'].value = keyword;
230	    const handler = this.els['search-form'].listeners.submit[0];
231	    return handler({ preventDefault(): void {} });
232	  }
233	
234	  // 点击“清空”按钮
235	  clearSearch(): void {
236	    this.els['search-clear'].listeners.click[0]({});
237	  }
238	
239	  articles(): El[] {
240	    return this.els.ideas.children.filter((node) => node.tagName === 'ARTICLE');
241	  }
242	
243	  titles(): string[] {
244	    return this.articles().map((article) => article.children.find((n) => n.tagName === 'H3')!.textContent);
245	  }
246	}
247	
248	function findScenario(article: El): El | undefined {
249	  return article.children.find(
250	    (node) =>
251	      node.tagName === 'P' &&
252	      node.children.some((child) => child.tagName === 'STRONG' && child.textContent === '使用场景：'),
253	  );
254	}
