256	// 校验一条已渲染的意见与原记录逐字段对应：标题、详细说明、非空使用场景、提交时间
257	function assertArticleMatches(article: El, idea: Record<string, unknown>): void {
258	  const heading = article.children.find((n) => n.tagName === 'H3')!;
259	  assert.equal(heading.textContent, idea.title);
