267	    expectsScenario,
268	    `使用场景展示与否应与记录一致：${String(idea.scenario)}`,
269	  );
270	  if (expectsScenario) {
271	    const span = scenarioNode!.children.find((n) => n.tagName === 'SPAN')!;
272	    assert.equal(span.textContent, idea.scenario);
273	  }
274	  const time = article.children.find((n) => n.tagName === 'TIME')!;
275	  assert.equal(time.dateTime, idea.createdAt);
276	}
