1098	// 提交提示归属：成功或失败提示只属于最近一次点击提交。用户可以在上一条请求还没返回时
1099	// 再次点击提交，更早请求迟到的任何结果都不能改动当前提示；但旧请求被服务确认保存的意见
1100	// 仍必须进入列表。下列用例精确控制两个 POST 的返回先后与结果类型。
1101	
1102	function settleGate(g: Gate, outcome: 'network-error' | 'server-reject' | 'broken-json' | 'missing-idea' | 'malformed-idea'): void {
1103	  if (outcome === 'network-error') {
1104	    g.reject(new TypeError('Failed to fetch'));
1105	  } else if (outcome === 'server-reject') {
1106	    g.resolve(jsonResponse(400, { error: '较早一次提交被拒绝' }));
1107	  } else if (outcome === 'broken-json') {
1108	    g.resolve(brokenJsonResponse(201));
1109	  } else if (outcome === 'malformed-idea') {
1110	    // 可解析的 201：标题、正文、场景都带回来了，但缺少 createdAt，记录结构仍不完整
1111	    g.resolve(jsonResponse(201, {
1112	      idea: { id: 'stale', title: '迟到的标题', description: '迟到的说明', scenario: '' },
1113	    }));
1114	  } else {
1115	    g.resolve(jsonResponse(201, { saved: true }));
1116	  }
1117	}
