1122	  { name: '201 但响应无法解析', outcome: 'broken-json' as const },
1123	  { name: '201 但内容不完整（缺 idea）', outcome: 'missing-idea' as const },
1124	  { name: '201 但意见结构异常（idea 缺 createdAt）', outcome: 'malformed-idea' as const },
