  await flush();
  assert.deepEqual(h.titles(), ['新的深色意见', '已有深色意见']);

  // 清空搜索后，暂时不可见的已保存意见按原有顺序出现
  h.clearSearch();
  assert.deepEqual(h.titles(), ['新的深色意见', '完全无关的标题', '已有深色意见']);
  assert.equal(h.articles().length, 3);
});

