import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { startServer, removeDataDir, type StartedServer } from '../testing/server.ts';

// 真实起一份 server.ts 的端到端冒烟测试：保护接口契约、字段规则与首页入口，
// 前端竞态行为的回归覆盖见 page.test.ts。

let server: StartedServer;

before(async () => {
  server = await startServer();
});

after(async () => {
  await server.stop();
  removeDataDir(server);
});

test('GET /health 返回服务状态和产品名称', async () => {
  const res = await fetch(`${server.origin}/health`);
  assert.equal(res.status, 200);
  assert.match(res.headers.get('content-type') ?? '', /application\/json/);
  const data = await res.json();
  assert.deepEqual(data, { status: 'ok', product: 'FeatureHarbor' });
});

test('GET / 返回首页：含提交表单、三个字段、空列表提示与内联脚本入口', async () => {
  const res = await fetch(`${server.origin}/`);
  assert.equal(res.status, 200);
  assert.match(res.headers.get('content-type') ?? '', /text\/html/);
  const html = await res.text();
  for (const expected of [
    '<form id="idea-form"',
    'id="f-title"',
    'id="f-desc"',
    'id="f-scenario"',
    'id="search-form"',
    'id="f-search"',
    'id="ideas"',
    '还没有意见记录。',
    "fetch('/api/ideas')",
  ]) {
    assert.ok(html.includes(expected), `首页应包含 ${expected}`);
  }
});

test('首次列表脚本运行前，空列表提示在初始 HTML 中即为 hidden（加载等待不能被误报为空）', async () => {
  const res = await fetch(`${server.origin}/`);
  const html = await res.text();
  assert.match(html, /<p id="empty"[^>]*hidden/);
});

test('空数据目录下 GET /api/ideas 返回空列表', async () => {
  const res = await fetch(`${server.origin}/api/ideas`);
  assert.equal(res.status, 200);
  const data = await res.json();
  assert.deepEqual(data, { ideas: [] });
});

test('POST 合法意见返回 201 且带 id/createdAt，随后列表可见且排在最前', async () => {
  const payload = { title: '支持深色模式', description: '希望界面支持深色模式。', scenario: '夜间使用' };
  const res = await fetch(`${server.origin}/api/ideas`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(payload),
  });
  assert.equal(res.status, 201);
  const data = await res.json();
  assert.ok(data.idea && typeof data.idea.id === 'string' && data.idea.id.length > 0);
  assert.equal(typeof data.idea.createdAt, 'string');
  assert.ok(!Number.isNaN(Date.parse(data.idea.createdAt)));
  assert.equal(data.idea.title, payload.title);
  assert.equal(data.idea.description, payload.description);
  assert.equal(data.idea.scenario, payload.scenario);

  const listRes = await fetch(`${server.origin}/api/ideas`);
  const list = await listRes.json();
  assert.equal(list.ideas[0].id, data.idea.id);
});

test('POST 省略可选 scenario 时按空字符串保存', async () => {
  const res = await fetch(`${server.origin}/api/ideas`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ title: '没有场景', description: '只有说明。' }),
  });
  assert.equal(res.status, 201);
  const data = await res.json();
  assert.equal(data.idea.scenario, '');
});

test('字段规则：空白标题、空白说明、超长标题、类型错误均返回 400 且不入库', async (t) => {
  const longTitle = '字'.repeat(121);
  const cases: Array<{ name: string; body: unknown }> = [
    { name: '标题为空白', body: { title: '   ', description: '说明' } },
    { name: '缺少标题', body: { description: '说明' } },
    { name: '说明为空白', body: { title: '标题', description: '   ' } },
    { name: '标题超长', body: { title: longTitle, description: '说明' } },
    { name: '标题不是字符串', body: { title: 1, description: '说明' } },
    { name: 'scenario 不是字符串', body: { title: '标题', description: '说明', scenario: 2 } },
    { name: '请求体不是 JSON 对象（数组）', body: [{ title: '标题', description: '说明' }] },
  ];
  for (const c of cases) {
    await t.test(c.name, async () => {
      const res = await fetch(`${server.origin}/api/ideas`, {
        method: 'POST',
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify(c.body),
      });
      assert.equal(res.status, 400);
      const data = await res.json();
      assert.equal(typeof data.error, 'string');
    });
  }
});

test('非法 JSON 请求体返回 400', async () => {
  const res = await fetch(`${server.origin}/api/ideas`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: '{not json',
  });
  assert.equal(res.status, 400);
});

test('同标题同正文的两次提交生成不同 id，列表中分别保留', async () => {
  const payload = { title: '重复标题', description: '重复说明' };
  const first = await fetch(`${server.origin}/api/ideas`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(payload),
  }).then((r) => r.json());
  const second = await fetch(`${server.origin}/api/ideas`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(payload),
  }).then((r) => r.json());
  assert.notEqual(first.idea.id, second.idea.id);

  const list = await fetch(`${server.origin}/api/ideas`).then((r) => r.json());
  const matches = list.ideas.filter(
    (idea: any) => idea.title === '重复标题' && idea.description === '重复说明',
  );
  assert.equal(matches.length, 2);
});

test('未知路径 404；已知路径不支持的方法 405', async () => {
  const notFound = await fetch(`${server.origin}/nope`);
  assert.equal(notFound.status, 404);

  const deleteIdea = await fetch(`${server.origin}/api/ideas`, { method: 'DELETE' });
  assert.equal(deleteIdea.status, 405);
  assert.match(deleteIdea.headers.get('allow') ?? '', /GET/);
  assert.match(deleteIdea.headers.get('allow') ?? '', /POST/);

  const postHealth = await fetch(`${server.origin}/health`, { method: 'POST' });
  assert.equal(postHealth.status, 405);
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { startServer, type StartedServer } from '../testing/server.ts';

// 读取兼容的回归保障：保护「已经保存的意见只按结构完整性读取，不重新套用新提交的内容限制」
// 这一现有行为。新意见的提交规则仍由接口与首页的内容校验约束（标题去首尾空白后非空、
// 最多 120 码点；详细说明含非空白内容、最多 5000 码点；使用场景最多 1000 码点），
// 但这些规则只能作用于新提交，读取历史记录时不能再套一遍——否则上限或空白要求一旦变化，
// 旧意见就会在列表接口变成整次加载失败。
//
// 本文件真实起一份 server.ts，启动前直接把「按今天的规则已无法提交、但记录结构完整」的
// 历史数据写入 ideas.json，只走公开的 GET/POST /api/ideas，覆盖：
//   - 标题/详细说明/使用场景超过当前上限、标题或详细说明只有空白的历史记录仍 200 返回，
//     长内容不截断、空白不替换为默认文字，首尾空白、换行、中文、表情与标记样文本逐字保留；
//   - scenario 为空字符串是正常记录（与缺少 scenario 字段不同），同样原样读取；
//   - 读取完成后再提交一条符合当前规则的新意见：201 且排在旧意见之前，
//     旧记录的内容、标识、时间与相对次序保持不变，SIGTERM 重启后仍然如此；
//   - 同样的超限或空白内容作为新意见提交时仍返回 400 字段错误，旧记录不受影响——
//     新旧内容的区别必须保留；
//   - 结构判定不能为了接受超限旧内容而放宽：混入缺字段或字段类型错误的记录时，
//     即使其中夹着结构完整的超限记录，整次读取仍 500 失败，磁盘内容逐字节保留。

interface Idea {
  id: string;
  title: string;
  description: string;
  scenario: string;
  createdAt: string;
}

const TITLE_LIMIT = 120;
const DESCRIPTION_LIMIT = 5000;
const SCENARIO_LIMIT = 1000;
const points = (text: string): number => Array.from(text).length;
const repeatCp = (char: string, times: number): string => char.repeat(times);

// 一组按今天的提交规则已无法新建、但结构完整的历史记录，刻意夹着一条普通意见，
// 用来证明读取时不会跳过内容特殊的记录、也不会只返回混在其中的普通意见。
// 磁盘上的数组次序就是接口返回次序（最新在前由写入方保证，读取方不重排）。
function legacyIdeas(): Idea[] {
  return [
    {
      id: 'legacy-over-title-0001',
      // 标题超过当前上限一个码点，且含首尾空白（历史标题不去空白、不截断）
      title: '  ' + repeatCp('长', TITLE_LIMIT + 1) + ' ',
      description: '标题超限历史记录的正文\n第二行保留换行 与中文😀',
      scenario: '标题超限记录的场景',
      createdAt: '2020-01-01T00:00:00.000Z',
    },
    {
      id: 'legacy-over-desc-0002',
      title: '正文超限的历史意见',
      // 详细说明恰好超过当前上限一个码点：5000 个中文 + 单个 😀
      description: repeatCp('描', DESCRIPTION_LIMIT) + '😀',
      scenario: '正文超限记录的场景 🌙',
      createdAt: '2020-02-02T00:02:00.000Z',
    },
    {
      id: 'legacy-over-scenario-0003',
      title: '  场景超限且标题首尾空白保留  ',
      description: '场景超限历史记录的正文',
      // 使用场景超过当前上限一个码点
      scenario: repeatCp('景', SCENARIO_LIMIT + 1),
      createdAt: '2020-03-03T00:03:00.000Z',
    },
    {
      // 混在特殊记录中间的普通意见：不能变成只显示这一条
      id: 'legacy-normal-0004',
      title: '混排在其中的普通意见',
      description: '完全符合当前规则的普通正文',
      scenario: '',
      createdAt: '2020-04-04T00:04:00.000Z',
    },
    {
      id: 'legacy-blank-title-0005',
      // 标题是空字符串与只有空白的两种边界之一：只有空白（空字符串另由 blank-title-empty 覆盖）
      title: '  \t\n ',
      description: '标题只有空白的历史正文，必须按原文读到，不能替换成默认标题',
      scenario: '空白标题记录的场景',
      createdAt: '2020-05-05T00:05:00.000Z',
    },
    {
      id: 'legacy-blank-desc-0006',
      title: '正文只有空白的历史意见',
      // 详细说明只有空白（含换行）：不能替换成默认正文，也不能判为读取失败
      description: '  \n\t  ',
      scenario: '',
      createdAt: '2020-06-06T00:06:00.000Z',
    },
    {
      id: 'legacy-markup-0007',
      // 标题首尾空白 + 尖括号/标记样文本：按普通文字读取，不解释成网页结构
      title: '  建议 <b>重点</b> 支持深色模式 😀  ',
      description: [
        '正文第一行保留换行',
        '脚本样文本 <script>alert("x")</script> 与实体原文 &lt;div&gt; &amp;',
        '末行含中文、表情与空白  😀  ',
      ].join('\n'),
      // scenario 为空字符串：正常记录，读取时原样保留为空，不能与缺少 scenario 字段混淆
      scenario: '',
      createdAt: 'not-a-date-but-a-string',
    },
    {
      id: 'legacy-empty-title-0008',
      // 标题就是空字符串：结构完整（字段存在且为字符串）即读取成功
      title: '',
      description: '标题为空字符串的历史正文',
      scenario: '空标题记录的场景',
      createdAt: '2020-08-08T00:08:00.000Z',
    },
    {
      id: 'legacy-empty-desc-0009',
      title: '正文为空字符串的历史意见',
      description: '',
      scenario: '空正文记录的场景\n第二行换行保留',
      createdAt: '2020-09-09T00:09:00.000Z',
    },

