+const VIEW_PATH_PREFIX = '/ideas/';
+// 单条意见查看页只展示常规字段（标题、完整详细说明、非空白使用场景、提交时间），
+// 记录携带的附加信息一律不在页面公开。与首页一样，历史内容不重新套用新提交的限制：
+// 超限、空白标题/说明、换行、中文、表情、网页标记样文本与实体写法都按原文显示。
+const VIEW_FIELD_LABELS = {
+  title: '标题',
+  description: '详细说明',
+  scenario: '使用场景',
+  createdAt: '提交时间',
+} as const;
